      });
      assert.equal(res.status, 201);
      const body = await res.json();
      assert.equal(body.tool.status, "borrowed");
      assert.equal(body.tool.loan.borrower, "Ben");
      assert.equal(typeof body.tool.loan.borrowedAt, "string");
    });
